type DescendantClickOptions = {
  selector: string;
  capture?: boolean;
  handler: (event: MouseEvent) => void;
};

/** Delegate native control activation, including the clicks generated by Enter and Space. */
export function descendantClicks(node: HTMLElement, initial: DescendantClickOptions) {
  let options = initial;
  const listener = (event: MouseEvent) => {
    const control = event.target instanceof Element ? event.target.closest(options.selector) : null;
    if (control && node.contains(control)) options.handler(event);
  };
  let capture = !!options.capture;
  node.addEventListener("click", listener, capture);
  return {
    update(next: DescendantClickOptions) {
      if (!!next.capture !== capture) {
        node.removeEventListener("click", listener, capture);
        capture = !!next.capture;
        node.addEventListener("click", listener, capture);
      }
      options = next;
    },
    destroy() {
      node.removeEventListener("click", listener, capture);
    },
  };
}

/** A container listens for shortcuts from its native interactive descendants. */
export function keyboardEvents(node: HTMLElement, initial: (event: KeyboardEvent) => void) {
  let handler = initial;
  const listener = (event: KeyboardEvent) => handler(event);
  node.addEventListener("keydown", listener);
  return {
    update(next: typeof initial) {
      handler = next;
    },
    destroy() {
      node.removeEventListener("keydown", listener);
    },
  };
}

/** Named scroll regions join the tab order only while they actually overflow. */
export function scrollRegion(node: HTMLElement, onKeyDown?: (event: KeyboardEvent) => void) {
  let handler = onKeyDown;
  const sync = () => {
    if (node.scrollWidth > node.clientWidth + 1 || node.scrollHeight > node.clientHeight + 1)
      node.tabIndex = 0;
    else node.removeAttribute("tabindex");
  };
  const listener = (event: KeyboardEvent) => handler?.(event);
  const observer = new ResizeObserver(sync);
  observer.observe(node);
  if (node.firstElementChild) observer.observe(node.firstElementChild);
  node.addEventListener("keydown", listener);
  sync();
  return {
    update(next: typeof onKeyDown) {
      handler = next;
      sync();
    },
    destroy() {
      observer.disconnect();
      node.removeEventListener("keydown", listener);
    },
  };
}
